    candidate_afterstate: Box<aspis_statement::pool_v1::PoolV1PairVerifiedAfterstateV1>,
    proof_length: usize,
}

struct ValidatedAsqa {
    statement: Box<PoolV1PairForestTerminalStatementV1>,
    proof_length: usize,
