pub(crate) trait PoolCpiRuntimeV1 {
    fn invoke<'info>(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'info>],
    ) -> ProgramResult;

    fn invoke_signed<'info>(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'info>],
        signer_seeds: &[&[&[u8]]],
    ) -> ProgramResult;

    fn close_program_account<'info>(
        &mut self,
        account: &AccountInfo<'info>,
        refund_authority: &AccountInfo<'info>,
        expected_owner: &Pubkey,
        expected_data_len: usize,
    ) -> ProgramResult {
        close_program_account_v1(account, refund_authority, expected_owner, expected_data_len)
    }
}

struct SolanaPoolCpiRuntimeV1;

impl PoolCpiRuntimeV1 for SolanaPoolCpiRuntimeV1 {
    fn invoke<'info>(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'info>],
    ) -> ProgramResult {
        program::invoke(instruction, account_infos)
    }

    fn invoke_signed<'info>(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'info>],
        signer_seeds: &[&[&[u8]]],
    ) -> ProgramResult {
        program::invoke_signed(instruction, account_infos, signer_seeds)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum FreshPdaPreparationV1 {
    CreateOrAllocateSystemOwned,
    ProgramOwnedZeroed,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum VaultPreparationV1 {
    CreateAndInitialize,
    InitializedEmpty,
}

fn solana_sha256(inputs: &[&[u8]]) -> [u8; 32] {
    solana_program::hash::hashv(inputs).to_bytes()
}

fn supported_program_loader(owner: &Pubkey) -> bool {
    owner == &bpf_loader::id()
        || owner == &bpf_loader_upgradeable::id()
        || owner == &loader_v4::id()
}

pub(crate) fn require_unique_accounts(accounts: &[AccountInfo<'_>]) -> ProgramResult {
    for left in 0..accounts.len() {
        for right in left + 1..accounts.len() {
            if accounts[left].key == accounts[right].key {
                return Err(ProgramError::InvalidArgument);
            }
        }
    }
    Ok(())
}

pub(crate) fn require_payer_and_system_program(
    payer: &AccountInfo<'_>,
    system_program_account: &AccountInfo<'_>,
) -> ProgramResult {
    if !payer.is_signer
        || !payer.is_writable
        || payer.executable
        || payer.owner != &system_program::id()
    {
        return Err(PoolV1ProgramError::InvalidPayer.into());
    }
    if system_program_account.key != &system_program::id()
        || system_program_account.owner != &native_loader::id()
        || !system_program_account.executable
        || system_program_account.is_signer
        || system_program_account.is_writable
    {
        return Err(PoolV1ProgramError::InvalidSystemProgram.into());
    }
    Ok(())
}

/// Tombstone, refund and deallocate one already authenticated Pool-owned
/// prepared-plan account. Closing is intentionally last in final settlement:
/// no later CPI can observe an instruction with temporarily changed lamports.
fn close_program_account_v1(
    account: &AccountInfo<'_>,
    refund_authority: &AccountInfo<'_>,
    expected_owner: &Pubkey,
    expected_data_len: usize,
) -> ProgramResult {
    if account.owner != expected_owner
        || account.executable
        || account.is_signer
        || !account.is_writable
        || refund_authority.key == account.key
        || !refund_authority.is_writable
        || account.data_len() != expected_data_len
    {
        return Err(ProgramError::InvalidAccountData);
    }

    // A full tombstone precedes the zero-lamport state. If a later operation
    // in this instruction fails, transaction rollback restores the plan; if
    // settlement succeeds, resize+System assignment prevent same-transaction
    // account revival from restoring a decodable ASPS/ASRS image.
    account.try_borrow_mut_data()?.fill(0xff);
    let refund = account.lamports();
    {
        let mut destination_lamports = refund_authority.try_borrow_mut_lamports()?;
        let mut account_lamports = account.try_borrow_mut_lamports()?;
        let next = (**destination_lamports)
            .checked_add(refund)
            .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
        **destination_lamports = next;
        **account_lamports = 0;
    }
    account.assign(&system_program::id());
    account.resize(0)?;
    Ok(())
}

pub(crate) fn plan_fresh_program_pda(
    account: &AccountInfo<'_>,
    program_id: &Pubkey,
    expected_address: &Pubkey,
    exact_bytes: usize,
) -> Result<FreshPdaPreparationV1, ProgramError> {
    if account.key != expected_address
        || account.executable
        || account.is_signer
        || !account.is_writable
    {
        return Err(PoolV1ProgramError::InvalidFreshAccount.into());
    }
    if account.owner == program_id {
        let data = account.try_borrow_data()?;
        if data.len() != exact_bytes || data.iter().any(|byte| *byte != 0) {
            return Err(PoolV1ProgramError::InvalidFreshAccount.into());
        }
        Ok(FreshPdaPreparationV1::ProgramOwnedZeroed)
    } else if account.owner == &system_program::id() && account.data_is_empty() {
        Ok(FreshPdaPreparationV1::CreateOrAllocateSystemOwned)
    } else {
        Err(PoolV1ProgramError::InvalidFreshAccount.into())
    }
}

pub(crate) fn create_or_allocate_pda<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    payer: &AccountInfo<'info>,
    account: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    exact_bytes: usize,
    owner: &Pubkey,
    signer_seeds: &[&[u8]],
) -> ProgramResult {
    let rent = Rent::get()?;
    create_or_allocate_pda_with_rent(
        runtime,
        payer,
        account,
        system_program_account,
        exact_bytes,
        owner,
        signer_seeds,
        &rent,
    )
}

pub(crate) fn create_or_allocate_pda_with_rent<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    payer: &AccountInfo<'info>,
    account: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    exact_bytes: usize,
    owner: &Pubkey,
    signer_seeds: &[&[u8]],
    rent: &Rent,
) -> ProgramResult {
    require_payer_and_system_program(payer, system_program_account)?;
    if account.owner != &system_program::id() || !account.data_is_empty() {
        return Err(PoolV1ProgramError::InvalidFreshAccount.into());
    }
    let required_lamports = rent.minimum_balance(exact_bytes).max(1);
    let infos = [
        payer.clone(),
        account.clone(),
        system_program_account.clone(),
    ];
    let signer_seed_sets = [signer_seeds];
    if account.lamports() == 0 {
        runtime.invoke_signed(
            &system_instruction::create_account(
                payer.key,
                account.key,
                required_lamports,
                exact_bytes as u64,
                owner,
            ),
            &infos,
            &signer_seed_sets,
        )?;
    } else {
        let deficit = required_lamports.saturating_sub(account.lamports());
        if deficit != 0 {
            runtime.invoke(
                &system_instruction::transfer(payer.key, account.key, deficit),
                &infos,
            )?;
        }
        runtime.invoke_signed(
            &system_instruction::allocate(account.key, exact_bytes as u64),
            &infos,
            &signer_seed_sets,
        )?;
        runtime.invoke_signed(
            &system_instruction::assign(account.key, owner),
            &infos,
            &signer_seed_sets,
        )?;
    }
    Ok(())
}

/// `create_with_seed` counterpart of [`create_or_allocate_pda_with_rent`]
/// (B1 marker). `base` is a Pool PDA that signs with `base_signer_seeds`;
/// `account` must be `create_with_seed(base, seed, owner)` (the System
/// program re-derives and checks it). A System-owned empty account with no
/// lamports is created with `CreateAccountWithSeed`; a prefunded one (anyone
/// may send lamports to the address first) is topped up with `Transfer` and
/// then given its space and owner with `AllocateWithSeed` and
/// `AssignWithSeed`.
#[allow(clippy::too_many_arguments)]
pub(crate) fn create_or_allocate_with_seed_with_rent<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    payer: &AccountInfo<'info>,
    account: &AccountInfo<'info>,
    base: &AccountInfo<'info>,
    seed: &str,
    system_program_account: &AccountInfo<'info>,
    exact_bytes: usize,
    owner: &Pubkey,
    base_signer_seeds: &[&[u8]],
    rent: &Rent,
) -> ProgramResult {
    require_payer_and_system_program(payer, system_program_account)?;
    if account.owner != &system_program::id() || !account.data_is_empty() {
        return Err(PoolV1ProgramError::InvalidFreshAccount.into());
    }
    let required_lamports = rent.minimum_balance(exact_bytes).max(1);
    let infos = [
        payer.clone(),
        account.clone(),
        base.clone(),
        system_program_account.clone(),
    ];
    let signer_seed_sets = [base_signer_seeds];
    if account.lamports() == 0 {
        runtime.invoke_signed(
            &system_instruction::create_account_with_seed(
                payer.key,
                account.key,
                base.key,
                seed,
                required_lamports,
                exact_bytes as u64,
                owner,
            ),
            &infos,
            &signer_seed_sets,
        )?;
    } else {
        let deficit = required_lamports.saturating_sub(account.lamports());
        if deficit != 0 {
            runtime.invoke(
                &system_instruction::transfer(payer.key, account.key, deficit),
                &infos,
            )?;
        }
        runtime.invoke_signed(
            &system_instruction::allocate_with_seed(
                account.key,
                base.key,
                seed,
                exact_bytes as u64,
                owner,
            ),
            &infos,
            &signer_seed_sets,
        )?;
        runtime.invoke_signed(
            &system_instruction::assign_with_seed(account.key, base.key, seed, owner),
            &infos,
            &signer_seed_sets,
        )?;
    }
    Ok(())
}

pub(crate) fn require_token_program_account(account: &AccountInfo<'_>) -> ProgramResult {
    if account.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || !account.executable
        || account.is_signer
        || account.is_writable
        || !supported_program_loader(account.owner)
    {
        return Err(PoolV1ProgramError::InvalidTokenProgram.into());
    }
    Ok(())
}

fn require_initialized_empty_vault(
    program_id: &Pubkey,
    pool: &Pubkey,
    mint: &Pubkey,
    vault: &AccountInfo<'_>,
) -> ProgramResult {
    if vault.key != &pool_v1_vault_token_account_address(program_id, pool).0
        || vault.owner != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || vault.executable
        || vault.is_signer
        || !vault.is_writable
    {
        return Err(PoolV1ProgramError::InvalidVaultTokenAddress.into());
    }
    let parsed = parse_legacy_token_account_v1(&vault.try_borrow_data()?)?;
    if parsed.mint != *mint
        || parsed.authority != pool_v1_vault_authority_address(program_id, pool).0
        || parsed.amount != 0
        || parsed.has_delegate
        || parsed.is_native
        || parsed.delegated_amount != 0
        || parsed.has_close_authority
    {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }
    Ok(())
}

pub(crate) fn plan_vault_initialization(
    program_id: &Pubkey,
    pool: &Pubkey,
    mint: &Pubkey,
    vault: &AccountInfo<'_>,
) -> Result<VaultPreparationV1, ProgramError> {
    if vault.key != &pool_v1_vault_token_account_address(program_id, pool).0
        || vault.executable
        || vault.is_signer
        || !vault.is_writable
    {
        return Err(PoolV1ProgramError::InvalidVaultTokenAddress.into());
    }
    if vault.owner == &system_program::id() && vault.data_is_empty() {
        Ok(VaultPreparationV1::CreateAndInitialize)
    } else {
        require_initialized_empty_vault(program_id, pool, mint, vault)?;
        Ok(VaultPreparationV1::InitializedEmpty)
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn initialize_vault_account<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    pool: &Pubkey,
    mint: &AccountInfo<'info>,
    vault: &AccountInfo<'info>,
    token_program: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    preparation: VaultPreparationV1,
) -> ProgramResult {
    if preparation == VaultPreparationV1::InitializedEmpty {
        return Ok(());
    }
    let (_, bump) = pool_v1_vault_token_account_address(program_id, pool);
    let bump_seed = [bump];
    let seeds: &[&[u8]] = &[POOL_V1_VAULT_TOKEN_ACCOUNT_SEED, pool.as_ref(), &bump_seed];
    create_or_allocate_pda(
        runtime,
        payer,
        vault,
        system_program_account,
        LEGACY_SPL_TOKEN_ACCOUNT_BYTES,
        &LEGACY_SPL_TOKEN_PROGRAM_ID,
        seeds,
    )?;

    let authority = pool_v1_vault_authority_address(program_id, pool).0;
    let mut data = Vec::with_capacity(33);
    data.push(SPL_TOKEN_INITIALIZE_ACCOUNT3_DISCRIMINANT);
    data.extend_from_slice(authority.as_ref());
    let instruction = Instruction {
        program_id: LEGACY_SPL_TOKEN_PROGRAM_ID,
        accounts: vec![
            AccountMeta::new(*vault.key, false),
            AccountMeta::new_readonly(*mint.key, false),
        ],
        data,
    };
    runtime.invoke(
        &instruction,
        &[vault.clone(), mint.clone(), token_program.clone()],
    )?;
    require_initialized_empty_vault(program_id, pool, mint.key, vault)
}

fn load_canonical_pool_state(
    program_id: &Pubkey,
    pool_account: &AccountInfo<'_>,
) -> Result<CanonicalPoolStateV1, ProgramError> {
    CanonicalPoolStateV1::decode_account(program_id, pool_account)
}

#[allow(clippy::too_many_arguments)]
fn create_program_pda_if_needed<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    payer: &AccountInfo<'info>,
    account: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    exact_bytes: usize,
    preparation: FreshPdaPreparationV1,
    signer_seeds: &[&[u8]],
) -> ProgramResult {
    if preparation == FreshPdaPreparationV1::CreateOrAllocateSystemOwned {
        create_or_allocate_pda(
            runtime,
            payer,
            account,
            system_program_account,
            exact_bytes,
            program_id,
            signer_seeds,
        )?;
    }
    Ok(())
}

fn require_fresh_rent_exempt_program_pda(
    account: &AccountInfo<'_>,
    program_id: &Pubkey,
    expected_address: &Pubkey,
    exact_bytes: usize,
    preparation: FreshPdaPreparationV1,
    rent: &Rent,
) -> ProgramResult {
    let is_fresh = match preparation {
        // `plan_fresh_program_pda` already scanned every byte and no CPI was
        // given this account before this check. Repeating the large zero scan
        // is redundant, especially for 8.5KB rollover pages/shards.
        FreshPdaPreparationV1::ProgramOwnedZeroed => {
            account.key == expected_address
                && account.owner == program_id
                && !account.executable
                && !account.is_signer
                && account.is_writable
                && account.data_len() == exact_bytes
        }
        // A just-created System account crossed a CPI boundary, so retain one
        // complete post-CPI owner/shape/zero-state validation.
        FreshPdaPreparationV1::CreateOrAllocateSystemOwned => {
            plan_fresh_program_pda(account, program_id, expected_address, exact_bytes)?
                == FreshPdaPreparationV1::ProgramOwnedZeroed
        }
    };
    if !is_fresh || !rent.is_exempt(account.lamports(), exact_bytes) {
        return Err(PoolV1ProgramError::InvalidFreshAccount.into());
    }
    Ok(())
}

#[inline(never)]
fn process_initialize_with_runtime_v1<'info, R: PoolCpiRuntimeV1, S: FnOnce(&[u8])>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    runtime: &mut R,
    set_return_data: S,
) -> ProgramResult {
    let initialization = decode_initialize_instruction_v1(instruction_data)?;
    let [payer, pool, page_zero, mint, vault, token_program, system_program_account] = accounts
    else {
        return Err(if accounts.len() < 7 {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    };
    require_unique_accounts(accounts)?;
    require_payer_and_system_program(payer, system_program_account)?;
    require_token_program_account(token_program)?;

    let mint_key = Pubkey::new_from_array(initialization.asset_mint);
    if mint.key != &mint_key
        || mint.owner != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || mint.executable
        || mint.is_signer
        || mint.is_writable
    {
        return Err(PoolV1ProgramError::InvalidMint.into());
    }
    parse_legacy_mint_v1(&mint.try_borrow_data()?)?;

    let (expected_pool, pool_bump) = pool_v1_state_address(program_id, &mint_key);
    let pool_preparation = plan_fresh_program_pda(
        pool,
        program_id,
        &expected_pool,
        POOL_V1_STATE_ACCOUNT_BYTES,
    )?;
    let (expected_page, page_bump) = crate::pool_v1_root_page_address(program_id, pool.key, 0);
    let page_preparation = plan_fresh_program_pda(
        page_zero,
        program_id,
        &expected_page,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
    )?;
    let vault_preparation = plan_vault_initialization(program_id, pool.key, &mint_key, vault)?;

    // Construct and encode the full state before the first CPI. This catches
    // every policy/identity/tree format error while all accounts are unchanged.
    PoolStateV1::genesis_boxed(pool.key, initialization)?.validate_encoding()?;

    let pool_bump_seed = [pool_bump];
    let pool_seeds: &[&[u8]] = &[POOL_V1_STATE_SEED, mint_key.as_ref(), &pool_bump_seed];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        pool,
        system_program_account,
        POOL_V1_STATE_ACCOUNT_BYTES,
        pool_preparation,
        pool_seeds,
    )?;
    let page_number = 0u64.to_le_bytes();
    let page_bump_seed = [page_bump];
    let page_seeds: &[&[u8]] = &[
        POOL_V1_ROOT_HISTORY_PAGE_SEED,
        pool.key.as_ref(),
        &page_number,
        &page_bump_seed,
    ];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        page_zero,
        system_program_account,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        page_preparation,
        page_seeds,
    )?;
    initialize_vault_account(
        runtime,
        program_id,
        pool.key,
        mint,
        vault,
        token_program,
        payer,
        system_program_account,
        vault_preparation,
    )?;

    initialize_pool_accounts_v1(
        program_id,
        &[pool.clone(), page_zero.clone()],
        initialization,
    )?;
    let receipt = encode_initialization_receipt_v1(pool.key, page_zero.key, vault.key);
    set_return_data(&receipt);
    Ok(())
}

fn deposit_rolls_to_next_page(state: &PoolStateV1) -> Result<bool, ProgramError> {
    let current_sequence = state.current_root_sequence();
    let next_sequence = current_sequence
        .checked_add(1)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    Ok(root_history_location(next_sequence).page_number
        != root_history_location(current_sequence).page_number)
}

#[inline(never)]
fn process_deposit_with_runtime_v1<'info, R: PoolCpiRuntimeV1>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    runtime: &mut R,
) -> ProgramResult {
    let request = decode_deposit_top_level_v1(instruction_data)?;
    let pool = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let state = load_canonical_pool_state(program_id, pool)?;
    let rollover = deposit_rolls_to_next_page(&state)?;
    if !rollover {
        let [pool, current_page, mint, source, source_authority, vault, token_program] = accounts
        else {
            return Err(if accounts.len() < 7 {
                ProgramError::NotEnoughAccountKeys
            } else {
                ProgramError::InvalidArgument
            });
        };
        require_unique_accounts(accounts)?;
        require_token_program_account(token_program)?;
        return process_prevalidated_vault_backed_deposit_v1(
            program_id,
            &[pool.clone(), current_page.clone()],
            &[
                mint.clone(),
                source.clone(),
                source_authority.clone(),
                vault.clone(),
                token_program.clone(),
            ],
            &state,
            request,
        );
    }

    let [pool, current_page, next_page, mint, source, source_authority, vault, token_program, payer, system_program_account] =
        accounts
    else {
        return Err(if accounts.len() < 10 {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    };
    require_unique_accounts(accounts)?;
    require_payer_and_system_program(payer, system_program_account)?;
    require_token_program_account(token_program)?;
    if current_page.is_signer || current_page.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    validate_current_history(program_id, pool, current_page, &state)?;
    let token_accounts = [
        mint.clone(),
        source.clone(),
        source_authority.clone(),
        vault.clone(),
        token_program.clone(),
    ];
    // Validate the entire economic transfer before creating the rollover page.
    plan_legacy_deposit_transfer_v1(
        program_id,
        pool.key,
        &state,
        &token_accounts,
        request.amount,
    )?;

    let next_page_number = root_history_location(state.current_root_sequence() + 1).page_number;
    let (expected_next, next_bump) =
        crate::pool_v1_root_page_address(program_id, pool.key, next_page_number);
    let preparation = plan_fresh_program_pda(
        next_page,
        program_id,
        &expected_next,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
    )?;
    let page_number_bytes = next_page_number.to_le_bytes();
    let bump_seed = [next_bump];
    let seeds: &[&[u8]] = &[
        POOL_V1_ROOT_HISTORY_PAGE_SEED,
        pool.key.as_ref(),
        &page_number_bytes,
        &bump_seed,
    ];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        next_page,
        system_program_account,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        preparation,
        seeds,
    )?;
    validate_new_page_account(program_id, pool.key, next_page_number, next_page)?;
    process_prevalidated_vault_backed_deposit_v1(
        program_id,
        &[pool.clone(), current_page.clone(), next_page.clone()],
        &token_accounts,
        &state,
        request,
    )
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SpendPageLayoutV1 {
    anchor_index: usize,
    current_index: usize,
    next_index: Option<usize>,
    suffix_start: usize,
    next_page_number: Option<u64>,
    next_page_bump: Option<u8>,
}

fn require_spend_capacity(state: &PoolStateV1, append_count: u64) -> ProgramResult {
    let next = state
        .current_root_sequence()
        .checked_add(append_count)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    if state.current_root_sequence() >= aspis_statement::pool_v1::POOL_V1_LEAF_CAPACITY {
        return Err(PoolV1ProgramError::TreeFull.into());
    }
    if next > aspis_statement::pool_v1::POOL_V1_LEAF_CAPACITY {
        return Err(PoolV1ProgramError::InsufficientTreeCapacity.into());
    }
    Ok(())
}

fn plan_spend_page_layout_v1(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    state: &PoolStateV1,
    anchor_sequence: u64,
    append_count: u64,
) -> Result<SpendPageLayoutV1, ProgramError> {
    require_spend_capacity(state, append_count)?;
    let pool = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let anchor_number = root_history_location(anchor_sequence).page_number;
    let current_number = root_history_location(state.current_root_sequence()).page_number;
    let first_number = root_history_location(state.current_root_sequence() + 1).page_number;
    let last_number =
        root_history_location(state.current_root_sequence() + append_count).page_number;
    if anchor_number > current_number
        || first_number < current_number
        || last_number > current_number.saturating_add(1)
    {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }

    let anchor_key = crate::pool_v1_root_page_address(program_id, pool.key, anchor_number).0;
    let current_key = crate::pool_v1_root_page_address(program_id, pool.key, current_number).0;
    let anchor_index = 1;
    let anchor_account = accounts
        .get(anchor_index)
        .ok_or(ProgramError::NotEnoughAccountKeys)?;
    if anchor_account.key != &anchor_key {
        return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
    }
    let mut cursor = 2;
    let current_index = if anchor_key == current_key {
        anchor_index
    } else {
        let index = cursor;
        cursor += 1;
        let current = accounts
            .get(index)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        if current.key != &current_key {
            return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
        }
        index
    };
    let current_writable = first_number == current_number;
    require_program_account(&accounts[current_index], program_id, current_writable)?;
    if accounts[current_index].is_signer {
        return Err(ProgramError::InvalidAccountData);
    }
    if current_index != anchor_index {
        require_program_account(anchor_account, program_id, false)?;
        if anchor_account.is_signer {
            return Err(ProgramError::InvalidAccountData);
        }
    }

    let (next_index, next_page_number, next_page_bump) = if last_number > current_number {
        let index = cursor;
        cursor += 1;
        let next = accounts
            .get(index)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        let (expected, bump) = crate::pool_v1_root_page_address(program_id, pool.key, last_number);
        if next.key != &expected {
            return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
        }
        (Some(index), Some(last_number), Some(bump))
    } else {
        (None, None, None)
    };
    Ok(SpendPageLayoutV1 {
        anchor_index,
        current_index,
        next_index,
        suffix_start: cursor,
        next_page_number,
        next_page_bump,
    })
}

fn validate_spend_binding_v1(
    pool: &AccountInfo<'_>,
    state: &PoolStateV1,
    transition_kind: PoolV1TransitionKind,
    envelope_kind: PoolV1TransitionKind,
    statement_pool: &[u8; 32],
    statement_domain: &[u8; 32],
    statement_asset_id: aspis_core::field::M31,
) -> ProgramResult {
    if envelope_kind != transition_kind
        || statement_pool != &pool.key.to_bytes()
        || statement_domain != &state.identity.deployment_domain
        || statement_asset_id != state.identity.asset_id
    {
        return Err(PoolV1ProgramError::VerifierDispatchIdentityMismatch.into());
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct PrepareSettlementRequestV1<'a> {
    transition_kind: PoolV1TransitionKind,
    request: AuthorizedAppendV1,
    anchor_sequence: u64,
    statement_pool: [u8; 32],
    statement_domain: [u8; 32],
    statement_asset_id: aspis_core::field::M31,
    statement_payload: &'a [u8],
    not_before_slot: u64,
    expires_at_slot: u64,
}

fn decode_prepare_settlement_request_v1(
    instruction_data: &[u8],
) -> Result<PrepareSettlementRequestV1<'_>, ProgramError> {
    let prepared = decode_prepare_settlement_instruction_v1(instruction_data)?;
    match prepared.transition_kind {
        PoolV1TransitionKind::PrivateTransfer => {
            let spend = decode_private_transfer_instruction_v1(prepared.spend_instruction)?;
            Ok(PrepareSettlementRequestV1 {
                transition_kind: PoolV1TransitionKind::PrivateTransfer,
                request: AuthorizedAppendV1::Two(
                    spend.statement.recipient_commitment,
                    spend.statement.change_commitment,
                ),
                anchor_sequence: spend.statement.anchor_sequence,
                statement_pool: spend.statement.pool,
                statement_domain: spend.statement.deployment_domain,
                statement_asset_id: spend.statement.asset_id,
                statement_payload: spend.statement_payload,
                not_before_slot: prepared.not_before_slot,
                expires_at_slot: prepared.expires_at_slot,
            })
        }
        PoolV1TransitionKind::Withdrawal => {
            let spend = decode_withdrawal_instruction_v1(prepared.spend_instruction)?;
            Ok(PrepareSettlementRequestV1 {
                transition_kind: PoolV1TransitionKind::Withdrawal,
                request: AuthorizedAppendV1::One(spend.statement.change_commitment),
                anchor_sequence: spend.statement.anchor_sequence,
                statement_pool: spend.statement.pool,
                statement_domain: spend.statement.deployment_domain,
                statement_asset_id: spend.statement.asset_id,
                statement_payload: spend.statement_payload,
                not_before_slot: prepared.not_before_slot,
                expires_at_slot: prepared.expires_at_slot,
            })
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PrepareSettlementPageLayoutV1 {
    anchor_index: usize,
    current_index: usize,
    next_index: Option<usize>,
    suffix_start: usize,
    next_page_number: Option<u64>,
    next_page_bump: Option<u8>,
}

/// Exact preparation-only page layout. Unlike the atomic spend layout, both
/// existing history pages are read-only because preparation persists only the
/// plan PDA(s). A rollover page is a fresh writable Pool PDA and remains all
/// zeroes until the later atomic settlement writes the authenticated image.
fn plan_prepare_settlement_page_layout_v1(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    state: &PoolStateV1,
    anchor_sequence: u64,
    append_count: u64,
) -> Result<PrepareSettlementPageLayoutV1, ProgramError> {
    require_spend_capacity(state, append_count)?;
    let pool = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let anchor_number = root_history_location(anchor_sequence).page_number;
    let current_number = root_history_location(state.current_root_sequence()).page_number;
    let last_number =
        root_history_location(state.current_root_sequence() + append_count).page_number;
    if anchor_number > current_number || last_number > current_number.saturating_add(1) {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }

    let anchor_key = crate::pool_v1_root_page_address(program_id, pool.key, anchor_number).0;
    let current_key = crate::pool_v1_root_page_address(program_id, pool.key, current_number).0;
    let anchor_index = 2;
    let anchor = accounts
        .get(anchor_index)
        .ok_or(ProgramError::NotEnoughAccountKeys)?;
    if anchor.key != &anchor_key {
        return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
    }
    require_program_account(anchor, program_id, false)?;
    if anchor.is_signer {
        return Err(ProgramError::InvalidAccountData);
    }

    let mut cursor = 3;
    let current_index = if anchor_key == current_key {
        anchor_index
    } else {
        let index = cursor;
        cursor += 1;
        let current = accounts
            .get(index)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        if current.key != &current_key {
            return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
        }
        require_program_account(current, program_id, false)?;
        if current.is_signer {
            return Err(ProgramError::InvalidAccountData);
        }
        index
    };

    let (next_index, next_page_number, next_page_bump) = if last_number > current_number {
        let index = cursor;
        cursor += 1;
        let next = accounts
            .get(index)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        let (expected, bump) = crate::pool_v1_root_page_address(program_id, pool.key, last_number);
        if next.key != &expected {
            return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
        }
        (Some(index), Some(last_number), Some(bump))
    } else {
        (None, None, None)
    };
    Ok(PrepareSettlementPageLayoutV1 {
        anchor_index,
        current_index,
        next_index,
        suffix_start: cursor,
        next_page_number,
        next_page_bump,
    })
}

#[allow(clippy::too_many_arguments)]
fn create_prepare_rollover_page_if_needed<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    layout: PrepareSettlementPageLayoutV1,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    rent: &Rent,
) -> Result<Option<PrevalidatedNewHistoryPageV1>, ProgramError> {
    let Some(next_index) = layout.next_index else {
        return Ok(None);
    };
    let next_page = &accounts[next_index];
    let page_number = layout
        .next_page_number
        .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
    let bump = layout
        .next_page_bump
        .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
    let preparation = plan_fresh_program_pda(
        next_page,
        program_id,
        &crate::pool_v1_root_page_address(program_id, accounts[1].key, page_number).0,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
    )?;
    let page_number_bytes = page_number.to_le_bytes();
    let bump_seed = [bump];
    let seeds: &[&[u8]] = &[
        POOL_V1_ROOT_HISTORY_PAGE_SEED,
        accounts[1].key.as_ref(),
        &page_number_bytes,
        &bump_seed,
    ];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        next_page,
        system_program_account,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        preparation,
        seeds,
    )?;
    require_fresh_rent_exempt_program_pda(
        next_page,
        program_id,
        &crate::pool_v1_root_page_address(program_id, accounts[1].key, page_number).0,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        preparation,
        rent,
    )?;
    prevalidate_new_history_page_v1(program_id, accounts[1].key, page_number, next_page).map(Some)
}

/// Prepare the exact state-bound settlement images and persist only their
/// Pool-owned core/shard PDAs. This is deliberately not final settlement: it
/// does not create a nullifier marker, mutate Pool/history state, transfer
/// vault assets, close/refund a plan, or emit an `ASTR` receipt.
#[allow(clippy::too_many_arguments)]
#[inline(never)]
pub(crate) fn process_prepare_settlement_with_runtime_v1<'info, R: PoolCpiRuntimeV1>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    current_slot: u64,
    rent: &Rent,
    hash: HashFn,
    runtime: &mut R,
) -> ProgramResult {
    let request = decode_prepare_settlement_request_v1(instruction_data)?;
    let payer = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let pool = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;
    // Preparation does not mutate the live Pool. Its source tree relation is
    // carried by the Pool program's inductive write invariant, so this path
    // retains every byte/PDA/ownership check while avoiding a redundant
    // depth-20 Poseidon reconstruction before computing the two new roots.
    let state = CanonicalPoolStateV1::decode_account_from_program_invariant(program_id, pool)?;
    validate_spend_binding_v1(
        pool,
        &state,
        request.transition_kind,
        request.transition_kind,
        &request.statement_pool,
        &request.statement_domain,
        request.statement_asset_id,
    )?;
    let layout = plan_prepare_settlement_page_layout_v1(
        program_id,
        accounts,
        &state,
        request.anchor_sequence,
        request.request.count(),
    )?;
    let has_rollover = layout.next_index.is_some();
    let expected_accounts = layout.suffix_start + if has_rollover { 6 } else { 5 };
    if accounts.len() != expected_accounts {
        return Err(if accounts.len() < expected_accounts {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    require_unique_accounts(accounts)?;

    let receipt = &accounts[layout.suffix_start];
    let registry_accounts = &accounts[layout.suffix_start + 1..layout.suffix_start + 3];
    let core_plan = &accounts[layout.suffix_start + 3];
    let rollover_plan = has_rollover.then(|| &accounts[layout.suffix_start + 4]);
    let system_program_account = &accounts[layout.suffix_start + if has_rollover { 5 } else { 4 }];
    require_payer_and_system_program(payer, system_program_account)?;

    // If this transition crosses a history-page boundary, materialize the
    // exact all-zero page before building the plan. Any later failure rolls
    // this CPI back atomically; the builder then validates that exact account.
    let prevalidated_next_page = create_prepare_rollover_page_if_needed(
        runtime,
        program_id,
        accounts,
        layout,
        payer,
        system_program_account,
        rent,
    )?;

    let supplied_next_page = layout.next_index.map(|index| &accounts[index]);
    let images = build_prepared_settlement_plan_v1(
        program_id,
        pool,
        &accounts[layout.anchor_index],
        &accounts[layout.current_index],
        supplied_next_page,
        prevalidated_next_page,
        &state,
        request.request,
        request.statement_payload,
        receipt,
        registry_accounts,
        payer.key,
        current_slot,
        request.not_before_slot,
        request.expires_at_slot,
        hash,
    )?;
    if core_plan.key != &images.core_address || images.rollover_shard.is_some() != has_rollover {
        return Err(PoolV1ProgramError::InvalidFreshAccount.into());
    }
    let core_preparation = plan_fresh_program_pda(
        core_plan,
        program_id,
        &images.core_address,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
    )?;
    let shard_preparation = match (rollover_plan, images.rollover_shard.as_ref()) {
        (None, None) => None,
        (Some(account), Some(shard)) if account.key == &shard.address => Some((
            account,
            shard,
            plan_fresh_program_pda(
                account,
                program_id,
                &shard.address,
                POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
            )?,
        )),
        _ => return Err(PoolV1ProgramError::InvalidFreshAccount.into()),
    };

    // `images` is returned only by the canonical internal encoder. Carry the
    // exact seed fields alongside its authenticated bytes rather than hashing
    // and decoding the just-created 10KB core and optional 8.5KB shard a
    // second time in the same instruction. Settlement still fully decodes
    // untrusted persisted plan accounts before applying them.
    let source_sequence_bytes = images.source_sequence.to_le_bytes();
    let core_bump_seed = [images.core_pda_bump];
    let core_seeds: &[&[u8]] = &[
        POOL_V1_PREPARED_SETTLEMENT_SEED,
        pool.key.as_ref(),
        &images.statement_digest,
        &source_sequence_bytes,
        payer.key.as_ref(),
        &core_bump_seed,
    ];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        core_plan,
        system_program_account,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
        core_preparation,
        core_seeds,
    )?;
    if let Some((account, shard, preparation)) = shard_preparation {
        let shard_bump_seed = [shard.pda_bump];
        let shard_seeds: &[&[u8]] = &[
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_SEED,
            core_plan.key.as_ref(),
            &shard_bump_seed,
        ];
        create_program_pda_if_needed(
            runtime,
            program_id,
            payer,
            account,
            system_program_account,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
            preparation,
            shard_seeds,
        )?;
    }

    // Recheck post-CPI ownership/zero state before the first plan byte is
    // persisted. This rejects a runtime/account substitution rather than
    // treating successful System instructions as sufficient evidence.
    require_fresh_rent_exempt_program_pda(
        core_plan,
        program_id,
        &images.core_address,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
        core_preparation,
        rent,
    )?;
    if let Some((account, shard, preparation)) = shard_preparation {
        require_fresh_rent_exempt_program_pda(
            account,
            program_id,
            &shard.address,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
            preparation,
            rent,
        )?;
    }

    core_plan
        .try_borrow_mut_data()?
        .copy_from_slice(images.core_image.as_ref());
    if let Some((account, shard, _)) = shard_preparation {
        account
            .try_borrow_mut_data()?
            .copy_from_slice(shard.image.as_ref());
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SettlePreparedLayoutV1 {
    current_index: usize,
    current_writable: bool,
    next_index: Option<usize>,
    marker_index: usize,
    receipt_index: usize,
    registry_start: usize,
    core_index: usize,
    shard_index: Option<usize>,
    system_index: usize,
    token_start: usize,
}

fn plan_settle_prepared_layout_v1(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    state: &PoolStateV1,
    transition_kind: PoolV1TransitionKind,
) -> Result<SettlePreparedLayoutV1, ProgramError> {
    let pool = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let append_count = match transition_kind {
        PoolV1TransitionKind::PrivateTransfer => 2,
        PoolV1TransitionKind::Withdrawal => 1,
    };
    require_spend_capacity(state, append_count)?;
    let source_sequence = state.current_root_sequence();
    let first_sequence = source_sequence
        .checked_add(1)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    let final_sequence = source_sequence
        .checked_add(append_count)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    let current_number = root_history_location(source_sequence).page_number;
    let first_number = root_history_location(first_sequence).page_number;
    let final_number = root_history_location(final_sequence).page_number;
    if first_number < current_number || final_number > current_number.saturating_add(1) {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }

    let current_index = 2;
    let current = accounts
        .get(current_index)
        .ok_or(ProgramError::NotEnoughAccountKeys)?;
    if current.key != &crate::pool_v1_root_page_address(program_id, pool.key, current_number).0 {
        return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
    }
    let current_writable = first_number == current_number;
    require_program_account(current, program_id, current_writable)?;
    if current.is_signer {
        return Err(ProgramError::InvalidAccountData);
    }

    let mut cursor = 3;
    let next_index = if final_number > current_number {
        let index = cursor;
        cursor += 1;
        let next = accounts
            .get(index)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        if next.key != &crate::pool_v1_root_page_address(program_id, pool.key, final_number).0 {
            return Err(PoolV1ProgramError::InvalidRootPageAddress.into());
        }
        require_program_account(next, program_id, true)?;
        if next.is_signer {
            return Err(ProgramError::InvalidAccountData);
        }
        Some(index)
    } else {
        None
    };

    let marker_index = cursor;
    let receipt_index = cursor + 1;
    let registry_start = cursor + 2;
    let core_index = cursor + 4;
    cursor += 5;
    let shard_index = if next_index.is_some() {
        let index = cursor;
        cursor += 1;
        Some(index)
    } else {
        None
    };
    let system_index = cursor;
    cursor += 1;
    let token_start = cursor;
    if transition_kind == PoolV1TransitionKind::Withdrawal {
        cursor += 5;
    }
    if accounts.len() != cursor {
        return Err(if accounts.len() < cursor {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    Ok(SettlePreparedLayoutV1 {
        current_index,
        current_writable,
        next_index,
        marker_index,
        receipt_index,
        registry_start,
        core_index,
        shard_index,
        system_index,
        token_start,
    })
}

fn require_prepared_plan_account_v1(
    account: &AccountInfo<'_>,
    program_id: &Pubkey,
    exact_data_len: usize,
) -> ProgramResult {
    if account.owner != program_id
        || account.executable
        || account.is_signer
        || !account.is_writable
        || account.data_len() != exact_data_len
    {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(())
}

/// Authenticate and retire one exact prepared plan without applying its Pool
/// transition. There is intentionally no Clock or Pool-state dependency: the
/// plan authority may cancel before activation, after expiry, or after source
/// state becomes stale. Account locking serializes cancellation with final
/// settlement, so only one instruction can successfully consume the plan.
#[inline(never)]
pub(crate) fn process_cancel_prepared_settlement_with_runtime_v1<'info, R, S>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    hash: HashFn,
    runtime: &mut R,
    set_return_data: S,
) -> ProgramResult
where
    R: PoolCpiRuntimeV1,
    S: FnOnce(&[u8]),
{
    let instruction = decode_cancel_prepared_settlement_instruction_v1(instruction_data)?;
    let expected_accounts = instruction.account_shape.account_count();
    if accounts.len() != expected_accounts {
        return Err(if accounts.len() < expected_accounts {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    require_unique_accounts(accounts)?;

    let plan_authority = &accounts[0];
    if !plan_authority.is_signer
        || !plan_authority.is_writable
        || plan_authority.executable
        || plan_authority.owner != &system_program::id()
    {
        return Err(PoolV1ProgramError::InvalidPayer.into());
    }
    let core_plan = &accounts[1];
    require_prepared_plan_account_v1(
        core_plan,
        program_id,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
    )?;
    let rollover_plan = instruction
        .account_shape
        .has_rollover_shard()
        .then(|| &accounts[2]);
    if let Some(shard) = rollover_plan {
        require_prepared_plan_account_v1(
            shard,
            program_id,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
        )?;
    }

    let core_data = core_plan.try_borrow_data()?;
    let shard_data = rollover_plan
        .map(|account| account.try_borrow_data())
        .transpose()?;
    let rollover_shard = match (rollover_plan, shard_data.as_ref()) {
        (Some(account), Some(image)) => Some(PreparedSettlementRolloverShardAccountV1 {
            address: account.key,
            owner: account.owner,
            image: image.as_ref(),
        }),
        (None, None) => None,
        _ => return Err(ProgramError::InvalidAccountData),
    };
    authorize_prepared_settlement_plan_close_v1(
        program_id,
        core_plan.key,
        core_plan.owner,
        core_data.as_ref(),
        rollover_shard,
        plan_authority.key,
        plan_authority.is_signer,
        hash,
    )?;

    drop(shard_data);
    drop(core_data);
    if let Some(shard) = rollover_plan {
        runtime.close_program_account(
            shard,
            plan_authority,
            program_id,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
        )?;
    }
    runtime.close_program_account(
        core_plan,
        plan_authority,
        program_id,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
    )?;

    let receipt = encode_cancel_prepared_settlement_instruction_v1(instruction.account_shape);
    set_return_data(&receipt);
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn create_nullifier_marker_if_needed_v1<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    pool: &Pubkey,
    marker_account: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    planned: PlannedNullifierMarkerV1,
    rent: &Rent,
) -> Result<PlannedNullifierMarkerV1, ProgramError> {
    if planned.preparation() == NullifierMarkerPreparationV1::CreateOrAllocateSystemOwned {
        let nullifier_bytes = planned.marker().canonical_nullifier_encoding();
        let bump_seed = [planned.address_bump()];
        let seeds: &[&[u8]] = &[
            POOL_V1_NULLIFIER_MARKER_SEED,
            pool.as_ref(),
            &nullifier_bytes,
            &bump_seed,
        ];
        create_or_allocate_pda_with_rent(
            runtime,
            payer,
            marker_account,
            system_program_account,
            POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
            program_id,
            seeds,
            rent,
        )?;
    }
    let ready = plan_nullifier_marker_consumption_v1(program_id, marker_account, planned.marker())?;
    if ready.preparation() != NullifierMarkerPreparationV1::PopulateProgramOwnedZeroed
        || ready.encoded_marker() != planned.encoded_marker()
        || !rent.is_exempt(
            marker_account.lamports(),
            POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
        )
    {
        return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
    }
    Ok(ready)
}

/// Create the pair-forest (B1) marker at `create_with_seed(master, seed,
/// program_id)` if it is still System-owned, signing as the master PDA
/// (`master_signer_seeds` = master seeds with the stored, authenticated
/// bump). The key was authenticated by the plan, so the re-check derives no
/// address: it only requires the now Pool-owned, exact-size, zeroed,
/// rent-exempt image.
#[allow(clippy::too_many_arguments)]
#[cfg(feature = "pair-forest-account-evidence")]
pub(crate) fn create_pair_forest_nullifier_marker_if_needed_v1<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    master_account: &AccountInfo<'info>,
    master_signer_seeds: &[&[u8]],
    marker_account: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    planned: crate::nullifier::PlannedPairForestNullifierMarkerV1,
    rent: &Rent,
) -> Result<crate::nullifier::PlannedPairForestNullifierMarkerV1, ProgramError> {
    if planned.preparation() == NullifierMarkerPreparationV1::CreateOrAllocateSystemOwned {
        create_or_allocate_with_seed_with_rent(
            runtime,
            payer,
            marker_account,
            master_account,
            crate::nullifier::pool_v1_pair_forest_marker_seed_str_v1(planned.seed())?,
            system_program_account,
            POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
            program_id,
            master_signer_seeds,
            rent,
        )?;
    }
    if crate::nullifier::recheck_pair_forest_nullifier_marker_v1(program_id, marker_account)?
        != NullifierMarkerPreparationV1::PopulateProgramOwnedZeroed
        || !rent.is_exempt(
            marker_account.lamports(),
            POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
        )
    {
        return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
    }
    Ok(planned)
}

/// Consume one exact ASPS/optional ASRS plan and perform the complete final
/// Pool transition in the same locked instruction. The pure apply gate owns
/// every statement/image comparison; this processor supplies live accounts,
/// performs only the authenticated custody action, and persists those images.
#[allow(clippy::too_many_arguments)]
#[inline(never)]
pub(crate) fn process_settle_prepared_with_runtime_v1<'info, R, S>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    settlement_slot: u64,
    rent: &Rent,
    hash: HashFn,
    runtime: &mut R,
    set_return_data: S,
) -> ProgramResult
where
    R: PoolCpiRuntimeV1,
    S: FnOnce(&[u8]),
{
    let instruction = decode_settle_prepared_instruction_v1(instruction_data)?;
    let plan_authority = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let pool = accounts.get(1).ok_or(ProgramError::NotEnoughAccountKeys)?;
    let state = load_canonical_pool_state(program_id, pool)?;
    let layout = plan_settle_prepared_layout_v1(
        program_id,
        accounts,
        state.as_state(),
        instruction.transition_kind,
    )?;
    require_unique_accounts(accounts)?;
    let system_program_account = &accounts[layout.system_index];
    require_payer_and_system_program(plan_authority, system_program_account)?;

    let core_plan = &accounts[layout.core_index];
    require_prepared_plan_account_v1(
        core_plan,
        program_id,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
    )?;
    let rollover_plan = layout.shard_index.map(|index| &accounts[index]);
    if let Some(shard) = rollover_plan {
        require_prepared_plan_account_v1(
            shard,
            program_id,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
        )?;
    }

    let authorization_receipt = &accounts[layout.receipt_index];
    let claim = authenticate_prepared_settlement_receipt_claim_v1(
        instruction.transition_kind,
        instruction.statement_payload,
        authorization_receipt,
        settlement_slot,
        hash,
    )?;
    if claim.transition_kind != instruction.transition_kind {
        return Err(ProgramError::InvalidAccountData);
    }
    let registry_accounts = &accounts[layout.registry_start..layout.registry_start + 2];
    let verifier_selection = authenticate_verifier_selection_v1(
        pool.key,
        &state.verifier_policy,
        registry_accounts,
        claim.verifier_selection,
        settlement_slot,
    )?;

    let marker = &accounts[layout.marker_index];
    let planned_marker = plan_nullifier_marker_consumption_v1(program_id, marker, claim.marker)?;

    let core_data = core_plan.try_borrow_data()?;
    let shard_data = rollover_plan
        .map(|account| account.try_borrow_data())
        .transpose()?;
    let source_pool_data = pool.try_borrow_data()?;
    let current_page = &accounts[layout.current_index];
    let source_current_data = current_page.try_borrow_data()?;
    let next_page = layout.next_index.map(|index| &accounts[index]);
    let source_next_data = next_page
        .map(|account| account.try_borrow_data())
        .transpose()?;
    let authorization_receipt_data = authorization_receipt.try_borrow_data()?;
    let rollover_shard = match (rollover_plan, shard_data.as_ref()) {
        (Some(account), Some(image)) => Some(PreparedSettlementRolloverShardAccountV1 {
            address: account.key,
            owner: account.owner,
            image: image.as_ref(),
        }),
        (None, None) => None,
        _ => return Err(ProgramError::InvalidAccountData),
    };
    let source_next = match (next_page, source_next_data.as_ref()) {
        (Some(account), Some(image)) => Some((account.key, image.as_ref())),
        (None, None) => None,
        _ => return Err(ProgramError::InvalidAccountData),
    };
    let applied = apply_prepared_settlement_plan_v1(PreparedSettlementApplyContextV1 {
        program_id,
        plan_address: core_plan.key,
        plan_owner: core_plan.owner,
        plan_authority: plan_authority.key,
        plan_image: &core_data,
        rollover_shard,
        pool_address: pool.key,
        source_pool_image: &source_pool_data,
        current_page_address: current_page.key,
        source_current_page_image: &source_current_data,
        next_page: source_next,
        statement_payload: instruction.statement_payload,
        expected_transition_kind: instruction.transition_kind,
        expected_statement_digest: claim.statement_digest,
        expected_nullifier: claim.nullifier,
        authorization_receipt_address: authorization_receipt.key,
        authorization_receipt_owner: authorization_receipt.owner,
        authorization_receipt_image: &authorization_receipt_data,
        authorization_receipt_is_signer: authorization_receipt.is_signer,
        authorization_receipt_is_writable: authorization_receipt.is_writable,
        authorization_receipt_executable: authorization_receipt.executable,
        verifier_selection,
        nullifier_marker_address: marker.key,
        nullifier_marker_plan: &planned_marker,
        settlement_slot,
        hash,
    })?;

    let withdrawal_plan = match applied.action.withdrawal_amount_and_destination() {
        Some((amount, destination)) => Some(plan_legacy_withdrawal_transfer_v1(
            program_id,
            pool.key,
            state.as_state(),
            &accounts[layout.token_start..layout.token_start + 5],
            &Pubkey::new_from_array(destination),
            amount,
        )?),
        None => None,
    };
    let (first_output, second_output_or_destination, withdrawal_amount, second_leaf_index, root) =
        match (
            instruction.transition_kind,
            applied.action.ordered_commitments(),
            applied.action.withdrawal_amount_and_destination(),
            applied.receipt.second,
        ) {
            (
                PoolV1TransitionKind::PrivateTransfer,
                (first, Some(second)),
                None,
                Some(second_receipt),
            ) => (
                first,
                encode_digest_canonical(&second),
                0,
                second_receipt.leaf_index,
                second_receipt,
            ),
            (
                PoolV1TransitionKind::Withdrawal,
                (first, None),
                Some((amount, destination)),
                None,
            ) => (first, destination, amount, 0, applied.receipt.first),
            _ => return Err(ProgramError::InvalidAccountData),
        };
    let receipt = encode_transition_receipt_v1(&TransitionReceiptV1 {
        transition_kind: instruction.transition_kind,
        pool: pool.key.to_bytes(),
        nullifier: claim.nullifier,
        first_output,
        second_output_or_destination,
        withdrawal_amount,
        first_leaf_index: applied.receipt.first.leaf_index,
        second_leaf_index,
        root_sequence: root.root_sequence,
        root: root.root,
    })?;

    // Release every source-image borrow before the first CPI or mutable state
    // copy. The apply result borrows only the authenticated plan image.
    drop(authorization_receipt_data);
    drop(source_next_data);
    drop(source_current_data);
    drop(source_pool_data);

    let ready_marker = create_nullifier_marker_if_needed_v1(
        runtime,
        program_id,
        pool.key,
        marker,
        plan_authority,
        system_program_account,
        planned_marker,
        rent,
    )?;
    if let Some(withdrawal) = withdrawal_plan.as_ref() {
        let token_accounts = &accounts[layout.token_start..layout.token_start + 5];
        let transfer_infos = exact_withdrawal_transfer_account_infos_v1(token_accounts)?;
        let bump_seed = [withdrawal.authority_bump];
        let authority_seeds: &[&[u8]] =
            &[POOL_V1_VAULT_AUTHORITY_SEED, pool.key.as_ref(), &bump_seed];
        runtime.invoke_signed(&withdrawal.instruction, &transfer_infos, &[authority_seeds])?;
        validate_exact_withdrawal_delta_v1(token_accounts, withdrawal)?;
    }

    pool.try_borrow_mut_data()?
        .copy_from_slice(applied.next_pool_image);
    if layout.current_writable {
        current_page
            .try_borrow_mut_data()?
            .copy_from_slice(applied.next_current_page_image);
    }
    match (next_page, applied.next_rollover_page_image) {
        (Some(account), Some(image)) => account.try_borrow_mut_data()?.copy_from_slice(image),
        (None, None) => {}
        _ => return Err(ProgramError::InvalidAccountData),
    }
    marker
        .try_borrow_mut_data()?
        .copy_from_slice(&ready_marker.encoded_marker());

    // No plan-backed reference remains after the state copies. Close the
    // shard first, then the core which authenticated it, and expose success
    // only after both refunds are complete.
    drop(shard_data);
    drop(core_data);
    if let Some(shard) = rollover_plan {
        runtime.close_program_account(
            shard,
            plan_authority,
            program_id,
            POOL_V1_PREPARED_SETTLEMENT_ROLLOVER_ACCOUNT_BYTES,
        )?;
    }
    runtime.close_program_account(
        core_plan,
        plan_authority,
        program_id,
        POOL_V1_PREPARED_SETTLEMENT_CORE_ACCOUNT_BYTES,
    )?;
    set_return_data(&receipt);
    Ok(())
}

fn plan_marker_from_envelope_v1(
    program_id: &Pubkey,
    marker_account: &AccountInfo<'_>,
    envelope: &aspis_statement::pool_v1::HistoricalAnchorEnvelopeV1,
) -> Result<PlannedNullifierMarkerV1, ProgramError> {
    plan_nullifier_marker_consumption_v1(
        program_id,
        marker_account,
        PoolV1NullifierMarkerV1::from_historical_anchor(envelope),
    )
}

fn create_next_root_page_if_needed<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    layout: SpendPageLayoutV1,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
) -> ProgramResult {
    let Some(next_index) = layout.next_index else {
        return Ok(());
    };
    let next_page = &accounts[next_index];
    let page_number = layout
        .next_page_number
        .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
    let bump = layout
        .next_page_bump
        .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
    let expected = crate::pool_v1_root_page_address(program_id, accounts[0].key, page_number).0;
    let preparation = plan_fresh_program_pda(
        next_page,
        program_id,
        &expected,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
    )?;
    let page_number_bytes = page_number.to_le_bytes();
    let bump_seed = [bump];
    let seeds: &[&[u8]] = &[
        POOL_V1_ROOT_HISTORY_PAGE_SEED,
        accounts[0].key.as_ref(),
        &page_number_bytes,
        &bump_seed,
    ];
    create_program_pda_if_needed(
        runtime,
        program_id,
        payer,
        next_page,
        system_program_account,
        POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        preparation,
        seeds,
    )?;
    validate_new_page_account(program_id, accounts[0].key, page_number, next_page)
}

fn state_accounts_for_append_v1<'info>(
    accounts: &[AccountInfo<'info>],
    layout: SpendPageLayoutV1,
) -> Vec<AccountInfo<'info>> {
    let mut state_accounts = Vec::with_capacity(if layout.next_index.is_some() { 3 } else { 2 });
    state_accounts.push(accounts[0].clone());
    state_accounts.push(accounts[layout.current_index].clone());
    if let Some(next_index) = layout.next_index {
        state_accounts.push(accounts[next_index].clone());
    }
    state_accounts
}

fn create_and_write_marker_v1<'info, R: PoolCpiRuntimeV1>(
    runtime: &mut R,
    program_id: &Pubkey,
    pool: &Pubkey,
    marker_account: &AccountInfo<'info>,
    payer: &AccountInfo<'info>,
    system_program_account: &AccountInfo<'info>,
    planned: PlannedNullifierMarkerV1,
) -> ProgramResult {
    if planned.preparation() == NullifierMarkerPreparationV1::CreateOrAllocateSystemOwned {
        let nullifier_bytes = planned.marker().canonical_nullifier_encoding();
        let bump_seed = [planned.address_bump()];
        let seeds: &[&[u8]] = &[
            POOL_V1_NULLIFIER_MARKER_SEED,
            pool.as_ref(),
            &nullifier_bytes,
            &bump_seed,
        ];
        create_or_allocate_pda(
            runtime,
            payer,
            marker_account,
            system_program_account,
            POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
            program_id,
            seeds,
        )?;
    }
    let ready = plan_nullifier_marker_consumption_v1(program_id, marker_account, planned.marker())?;
    if ready.preparation() != NullifierMarkerPreparationV1::PopulateProgramOwnedZeroed
        || ready.encoded_marker() != planned.encoded_marker()
    {
        return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
    }
    let mut data = marker_account.try_borrow_mut_data()?;
    data.copy_from_slice(&planned.encoded_marker());
    Ok(())
}

#[allow(clippy::too_many_arguments)]
#[inline(never)]
fn process_private_transfer_with_runtime_v1<'info, R, V, S>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    current_slot: u64,
    hash: HashFn,
    runtime: &mut R,
    verify: V,
    set_return_data: S,
) -> ProgramResult
where
    R: PoolCpiRuntimeV1,
    V: FnOnce(
        &Pubkey,
        &[u8],
        &[u8],
        &PoolStateV1,
        &[AccountInfo<'info>],
        &AccountInfo<'info>,
        &AccountInfo<'info>,
        VerifierDispatchClaimV1,
        u64,
    ) -> ProgramResult,
    S: FnOnce(&[u8]),
{
    let decoded = decode_private_transfer_instruction_v1(instruction_data)?;
    let pool = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let state = load_canonical_pool_state(program_id, pool)?;
    validate_spend_binding_v1(
        pool,
        &state,
        PoolV1TransitionKind::PrivateTransfer,
        decoded.envelope.transition_kind,
        &decoded.statement.pool,
        &decoded.statement.deployment_domain,
        decoded.statement.asset_id,
    )?;
    let layout = plan_spend_page_layout_v1(
        program_id,
        accounts,
        &state,
        decoded.envelope.anchor_sequence,
        2,
    )?;
    let expected_accounts = layout.suffix_start + 7;
    if accounts.len() != expected_accounts {
        return Err(if accounts.len() < expected_accounts {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    require_unique_accounts(accounts)?;
    let marker = &accounts[layout.suffix_start];
    let payer = &accounts[layout.suffix_start + 1];
    let system_program_account = &accounts[layout.suffix_start + 2];
    let registry_accounts = &accounts[layout.suffix_start + 3..layout.suffix_start + 5];
    let verifier_program = &accounts[layout.suffix_start + 5];
    let proof = &accounts[layout.suffix_start + 6];
    require_payer_and_system_program(payer, system_program_account)?;

    let encoded_envelope = encode_historical_anchor_envelope_v1(&decoded.envelope)
        .map_err(|_| PoolV1ProgramError::InvalidHistoricalAnchorEnvelope)?;
    let authenticated_anchor = authenticate_historical_anchor_after_prevalidated_state_v1(
        program_id,
        pool,
        &accounts[layout.anchor_index],
        &encoded_envelope,
        HistoricalAnchorAuthorizationV1 {
            transition_kind: PoolV1TransitionKind::PrivateTransfer,
            verifier_profile: decoded.envelope.verifier_profile,
            verifier_release: decoded.envelope.verifier_release,
        },
        &state,
    )?;
    let current_history = validate_current_history_after_prevalidated_anchor_v1(
        program_id,
        pool,
        &accounts[layout.current_index],
        &state,
        authenticated_anchor,
    )?;
    let planned_marker = plan_marker_from_envelope_v1(program_id, marker, &decoded.envelope)?;
    if let Some(next_index) = layout.next_index {
        let page_number = layout
            .next_page_number
            .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
        let expected = crate::pool_v1_root_page_address(program_id, pool.key, page_number).0;
        plan_fresh_program_pda(
            &accounts[next_index],
            program_id,
            &expected,
            POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        )?;
    }
    let claim = derive_verifier_dispatch_claim_v1(verifier_program, proof, hash)?;
    verify(
        pool.key,
        &encoded_envelope,
        decoded.statement_payload,
        &state,
        registry_accounts,
        verifier_program,
        proof,
        claim,
        current_slot,
    )?;

    create_next_root_page_if_needed(
        runtime,
        program_id,
        accounts,
        layout,
        payer,
        system_program_account,
    )?;
    let state_accounts = state_accounts_for_append_v1(accounts, layout);
    // `state` is the sealed result of the complete fail-closed decode above.
    // No intervening CPI receives the Pool account, so reuse it here rather
    // than repeating the depth-20 source reconstruction and the standalone
    // append path's source/post-state reconstructions.
    let append = apply_authorized_append_after_prevalidated_history_v1(
        program_id,
        &state_accounts,
        &state,
        current_history,
        AuthorizedAppendV1::Two(
            decoded.statement.recipient_commitment,
            decoded.statement.change_commitment,
        ),
        || {
            let replanned = plan_marker_from_envelope_v1(program_id, marker, &decoded.envelope)?;
            if replanned != planned_marker {
                return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
            }
            create_and_write_marker_v1(
                runtime,
                program_id,
                pool.key,
                marker,
                payer,
                system_program_account,
                replanned,
            )
        },
    )?;
    let second = append.second.ok_or(ProgramError::InvalidAccountData)?;
    let receipt = encode_transition_receipt_v1(&TransitionReceiptV1 {
        transition_kind: PoolV1TransitionKind::PrivateTransfer,
        pool: pool.key.to_bytes(),
        nullifier: decoded.statement.nullifier,
        first_output: decoded.statement.recipient_commitment,
        second_output_or_destination: encode_digest_canonical(&decoded.statement.change_commitment),
        withdrawal_amount: 0,
        first_leaf_index: append.first.leaf_index,
        second_leaf_index: second.leaf_index,
        root_sequence: second.leaf_index + 1,
        root: second.root,
    })?;
    set_return_data(&receipt);
    Ok(())
}

#[allow(clippy::too_many_arguments)]
#[inline(never)]
fn process_withdrawal_with_runtime_v1<'info, R, V, S>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'info>],
    instruction_data: &[u8],
    current_slot: u64,
    hash: HashFn,
    runtime: &mut R,
    verify: V,
    set_return_data: S,
) -> ProgramResult
where
    R: PoolCpiRuntimeV1,
    V: FnOnce(
        &Pubkey,
        &[u8],
        &[u8],
        &PoolStateV1,
        &[AccountInfo<'info>],
        &AccountInfo<'info>,
        &AccountInfo<'info>,
        VerifierDispatchClaimV1,
        u64,
    ) -> ProgramResult,
    S: FnOnce(&[u8]),
{
    let decoded = decode_withdrawal_instruction_v1(instruction_data)?;
    let pool = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    let state = load_canonical_pool_state(program_id, pool)?;
    validate_spend_binding_v1(
        pool,
        &state,
        PoolV1TransitionKind::Withdrawal,
        decoded.envelope.transition_kind,
        &decoded.statement.pool,
        &decoded.statement.deployment_domain,
        decoded.statement.asset_id,
    )?;
    let layout = plan_spend_page_layout_v1(
        program_id,
        accounts,
        &state,
        decoded.envelope.anchor_sequence,
        1,
    )?;
    let expected_accounts = layout.suffix_start + 7 + 5;
    if accounts.len() != expected_accounts {
        return Err(if accounts.len() < expected_accounts {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    require_unique_accounts(accounts)?;
    let marker = &accounts[layout.suffix_start];
    let payer = &accounts[layout.suffix_start + 1];
    let system_program_account = &accounts[layout.suffix_start + 2];
    let registry_accounts = &accounts[layout.suffix_start + 3..layout.suffix_start + 5];
    let verifier_program = &accounts[layout.suffix_start + 5];
    let proof = &accounts[layout.suffix_start + 6];
    let token_accounts = &accounts[layout.suffix_start + 7..layout.suffix_start + 12];
    require_payer_and_system_program(payer, system_program_account)?;
    require_token_program_account(&token_accounts[4])?;

    let encoded_envelope = encode_historical_anchor_envelope_v1(&decoded.envelope)
        .map_err(|_| PoolV1ProgramError::InvalidHistoricalAnchorEnvelope)?;
    authenticate_historical_anchor_v1(
        program_id,
        pool,
        &accounts[layout.anchor_index],
        &encoded_envelope,
        HistoricalAnchorAuthorizationV1 {
            transition_kind: PoolV1TransitionKind::Withdrawal,
            verifier_profile: decoded.envelope.verifier_profile,
            verifier_release: decoded.envelope.verifier_release,
        },
    )?;
    validate_current_history(program_id, pool, &accounts[layout.current_index], &state)?;
    let planned_marker = plan_marker_from_envelope_v1(program_id, marker, &decoded.envelope)?;
    if let Some(next_index) = layout.next_index {
        let page_number = layout
            .next_page_number
            .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
        let expected = crate::pool_v1_root_page_address(program_id, pool.key, page_number).0;
        plan_fresh_program_pda(
            &accounts[next_index],
            program_id,
            &expected,
            POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
        )?;
    }
    let destination = Pubkey::new_from_array(decoded.statement.destination_token_account);
    let withdrawal_plan = plan_legacy_withdrawal_transfer_v1(
        program_id,
        pool.key,
        &state,
        token_accounts,
        &destination,
        decoded.statement.amount,
    )?;
    let transfer_infos = exact_withdrawal_transfer_account_infos_v1(token_accounts)?;
    let claim = derive_verifier_dispatch_claim_v1(verifier_program, proof, hash)?;
    verify(
        pool.key,
        &encoded_envelope,
        decoded.statement_payload,
        &state,
        registry_accounts,
        verifier_program,
        proof,
        claim,
        current_slot,
    )?;

    create_next_root_page_if_needed(
        runtime,
        program_id,
        accounts,
        layout,
        payer,
        system_program_account,
    )?;
    let state_accounts = state_accounts_for_append_v1(accounts, layout);
    let append = apply_authorized_append_after_v1(
        program_id,
        &state_accounts,
        AuthorizedAppendV1::One(decoded.statement.change_commitment),
        || {
            let replanned = plan_marker_from_envelope_v1(program_id, marker, &decoded.envelope)?;
            if replanned != planned_marker {
                return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
            }
            if replanned.preparation() == NullifierMarkerPreparationV1::CreateOrAllocateSystemOwned
            {
                let nullifier_bytes = replanned.marker().canonical_nullifier_encoding();
                let bump_seed = [replanned.address_bump()];
                let seeds: &[&[u8]] = &[
                    POOL_V1_NULLIFIER_MARKER_SEED,
                    pool.key.as_ref(),
                    &nullifier_bytes,
                    &bump_seed,
                ];
                create_or_allocate_pda(
                    runtime,
                    payer,
                    marker,
                    system_program_account,
                    POOL_V1_NULLIFIER_MARKER_ACCOUNT_BYTES,
                    program_id,
                    seeds,
                )?;
            }

            let bump_seed = [withdrawal_plan.authority_bump];
            let authority_seeds: &[&[u8]] =
                &[POOL_V1_VAULT_AUTHORITY_SEED, pool.key.as_ref(), &bump_seed];
            runtime.invoke_signed(
                &withdrawal_plan.instruction,
                &transfer_infos,
                &[authority_seeds],
            )?;
            validate_exact_withdrawal_delta_v1(token_accounts, &withdrawal_plan)?;

            let ready = plan_marker_from_envelope_v1(program_id, marker, &decoded.envelope)?;
            if ready.preparation() != NullifierMarkerPreparationV1::PopulateProgramOwnedZeroed
                || ready.encoded_marker() != replanned.encoded_marker()
            {
                return Err(PoolV1ProgramError::InvalidNullifierMarkerAccount.into());
            }
            marker
                .try_borrow_mut_data()?
                .copy_from_slice(&ready.encoded_marker());
            Ok(())
        },
    )?;
    let receipt = encode_transition_receipt_v1(&TransitionReceiptV1 {
        transition_kind: PoolV1TransitionKind::Withdrawal,
        pool: pool.key.to_bytes(),
        nullifier: decoded.statement.nullifier,
        first_output: decoded.statement.change_commitment,
        second_output_or_destination: decoded.statement.destination_token_account,
        withdrawal_amount: decoded.statement.amount,
        first_leaf_index: append.first.leaf_index,
        second_leaf_index: 0,
        root_sequence: append.first.leaf_index + 1,
        root: append.first.root,
    })?;
    set_return_data(&receipt);
    Ok(())
}

#[allow(clippy::too_many_arguments)]
#[inline(never)]
fn dispatch_selected_verifier_v1<'info>(
    pool: &Pubkey,
    encoded_envelope: &[u8],
    statement_payload: &[u8],
    state: &PoolStateV1,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program: &AccountInfo<'info>,
    proof: &AccountInfo<'info>,
    claim: VerifierDispatchClaimV1,
    current_slot: u64,
) -> ProgramResult {
    dispatch_authenticated_verifier_readonly_v1(
        pool,
        &state.identity.deployment_domain,
        &state.verifier_policy,
        registry_accounts,
        verifier_program,
        proof,
        encoded_envelope,
        statement_payload,
        claim,
        current_slot,
        solana_sha256,
    )?;
    Ok(())
}

/// Exact native Pool dispatcher. Return data is cleared at entry and again on
/// every error, so an accepted verifier's intermediate `ASVS` cannot escape a
/// later failed marker/tree/vault transition.
#[inline(never)]
pub fn process_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'_>],
    instruction_data: &[u8],
) -> ProgramResult {
    program::set_return_data(&[]);
    // The finalized wallet/indexer authenticates transaction-level Pool
    // instructions.  Rejecting CPI here prevents an inner invocation from
    // advancing the append-only tree without a corresponding top-level scan
    // record.  Host unit tests exercise the pure predicate below; LiteSVM and
    // validator release gates exercise the production syscall.
    #[cfg(target_os = "solana")]
    require_transaction_level_invocation_v1(get_stack_height())?;
    let magic = instruction_data
        .get(..4)
        .ok_or(ProgramError::InvalidInstructionData)?;
    let mut runtime = SolanaPoolCpiRuntimeV1;
    let result = if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8I" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_initialize_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8C" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_checkpoint_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8D" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_deposit_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"ASQ8" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let slot = Clock::get()?.slot;
            let rent = Rent::get()?;
            process_pair_forest_terminal_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-full-asf8-audit") && magic == b"ASF8" {
        #[cfg(feature = "pair-forest-full-asf8-audit")]
        {
            let slot = Clock::get()?.slot;
            let rent = Rent::get()?;
            process_pair_forest_terminal_full_asf8_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-full-asf8-audit"))]
        unreachable!()
    } else if magic == POOL_V1_INITIALIZE_INSTRUCTION_MAGIC {
        process_initialize_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            &mut runtime,
            program::set_return_data,
        )
    } else if magic == POOL_V1_DEPOSIT_INSTRUCTION_MAGIC {
        process_deposit_with_runtime_v1(program_id, accounts, instruction_data, &mut runtime)
    } else if magic == POOL_V1_PREPARE_SETTLEMENT_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        let rent = Rent::get()?;
        process_prepare_settlement_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            &rent,
            solana_sha256,
            &mut runtime,
        )
    } else if magic == POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC {
        process_cancel_prepared_settlement_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            solana_sha256,
            &mut runtime,
            program::set_return_data,
        )
    } else if magic == POOL_V1_SETTLE_PREPARED_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        let rent = Rent::get()?;
        process_settle_prepared_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            &rent,
            solana_sha256,
            &mut runtime,
            program::set_return_data,
        )
    } else if cfg!(feature = "pair-afterstate-evidence")
        && magic == crate::instruction::POOL_V1_PAIR_PRIVATE_TRANSFER_INSTRUCTION_MAGIC
    {
        #[cfg(feature = "pair-afterstate-evidence")]
        {
            let slot = Clock::get()?.slot;
            process_pair_private_transfer_with_verifier_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                solana_sha256,
                dispatch_pair_verified_afterstate_readonly_v1,
                program::set_return_data,
            )
        }
        #[cfg(not(feature = "pair-afterstate-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-afterstate-evidence")
        && magic == crate::instruction::POOL_V1_PAIR_WITHDRAWAL_INSTRUCTION_MAGIC
    {
        #[cfg(feature = "pair-afterstate-evidence")]
        {
            let slot = Clock::get()?.slot;
            process_pair_withdrawal_with_verifier_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                solana_sha256,
                &mut runtime,
                dispatch_pair_verified_afterstate_readonly_v1,
                program::set_return_data,
            )
        }
        #[cfg(not(feature = "pair-afterstate-evidence"))]
        unreachable!()
    } else if magic == POOL_V1_PRIVATE_TRANSFER_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        process_private_transfer_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            solana_sha256,
            &mut runtime,
            dispatch_selected_verifier_v1,
            program::set_return_data,
        )
    } else if magic == POOL_V1_WITHDRAWAL_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        process_withdrawal_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            solana_sha256,
            &mut runtime,
            dispatch_selected_verifier_v1,
            program::set_return_data,
        )
    } else {
        Err(ProgramError::InvalidInstructionData)
    };
    if result.is_err() {
        program::set_return_data(&[]);
    }
    result
}

#[cfg(any(target_os = "solana", test))]
#[inline(always)]
fn require_transaction_level_invocation_v1(stack_height: usize) -> ProgramResult {
    if stack_height != TRANSACTION_LEVEL_STACK_HEIGHT {
        return Err(PoolV1ProgramError::CpiInvocationForbidden.into());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::M31;
    use aspis_statement::{
        pool_v1::{decode_pool_v1_nullifier_marker, HistoricalAnchorEnvelopeV1, VerifierPolicyV1},
        poseidon2::Digest,
    };
    use solana_program::clock::Epoch;
    use std::{cell::RefCell, vec};

    use crate::instruction::{
        encode_initialize_instruction_v1, encode_private_transfer_instruction_v1,
        encode_withdrawal_instruction_v1, PrivateTransferStatementV1, WithdrawalStatementV1,
    };
    use crate::state::PoolInitializationV1;

    struct NoCpi;

    impl PoolCpiRuntimeV1 for NoCpi {
        fn invoke<'info>(&mut self, _: &Instruction, _: &[AccountInfo<'info>]) -> ProgramResult {
            panic!("unexpected CPI")
        }

        fn invoke_signed<'info>(
            &mut self,
            _: &Instruction,
            _: &[AccountInfo<'info>],
            _: &[&[&[u8]]],
        ) -> ProgramResult {
            panic!("unexpected signed CPI")
        }
    }

    struct WithdrawalCpi {
        called: bool,
        expected_amount: u64,
    }

    impl PoolCpiRuntimeV1 for WithdrawalCpi {
        fn invoke<'info>(&mut self, _: &Instruction, _: &[AccountInfo<'info>]) -> ProgramResult {
            panic!("unexpected unsigned CPI")
        }

        fn invoke_signed<'info>(
            &mut self,
            instruction: &Instruction,
            infos: &[AccountInfo<'info>],
            signer_seeds: &[&[&[u8]]],
        ) -> ProgramResult {
            assert_eq!(instruction.program_id, LEGACY_SPL_TOKEN_PROGRAM_ID);
            assert_eq!(instruction.data[0], 12);
            assert_eq!(
                u64::from_le_bytes(instruction.data[1..9].try_into().unwrap()),
                self.expected_amount
            );
            assert_eq!(infos.len(), 5);
            assert_eq!(signer_seeds.len(), 1);
            let vault_before = {
                let data = infos[0].try_borrow_data()?;
                u64::from_le_bytes(data[64..72].try_into().unwrap())
            };
            let destination_before = {
                let data = infos[2].try_borrow_data()?;
                u64::from_le_bytes(data[64..72].try_into().unwrap())
            };
            let vault_after = vault_before
                .checked_sub(self.expected_amount)
                .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
            let destination_after = destination_before
                .checked_add(self.expected_amount)
                .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
            infos[0].try_borrow_mut_data()?[64..72].copy_from_slice(&vault_after.to_le_bytes());
            infos[2].try_borrow_mut_data()?[64..72]
                .copy_from_slice(&destination_after.to_le_bytes());
            self.called = true;
            Ok(())
        }
    }

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31(seed + 23 * index as u32))
    }

    fn policy() -> VerifierPolicyV1 {
        VerifierPolicyV1 {
            flags: 0,
            registry_program: [6u8; 32],
            registry_authority: [7u8; 32],
            policy_binding: [8u8; 32],
        }
    }

    fn initialization(mint: &Pubkey) -> PoolInitializationV1 {
        PoolInitializationV1 {
            asset_mint: mint.to_bytes(),
            token_program: LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes(),
            asset_id: M31(9),
            deployment_domain: [10u8; 32],
            verifier_policy: policy(),
        }
    }

    fn account<'a>(
        key: &'a Pubkey,
        owner: &'a Pubkey,
        lamports: &'a mut u64,
        data: &'a mut [u8],
        signer: bool,
        writable: bool,
        executable: bool,
    ) -> AccountInfo<'a> {
        AccountInfo::new(
            key,
            signer,
            writable,
            lamports,
            data,
            owner,
            executable,
            Epoch::default(),
        )
    }

    fn mint_data(decimals: u8) -> [u8; crate::LEGACY_SPL_TOKEN_MINT_ACCOUNT_BYTES] {
        let mut data = [0u8; crate::LEGACY_SPL_TOKEN_MINT_ACCOUNT_BYTES];
        data[44] = decimals;
        data[45] = 1;
        data
    }

    fn token_data(
        mint: &Pubkey,
        authority: &Pubkey,
        amount: u64,
    ) -> [u8; LEGACY_SPL_TOKEN_ACCOUNT_BYTES] {
        let mut data = [0u8; LEGACY_SPL_TOKEN_ACCOUNT_BYTES];
        data[..32].copy_from_slice(mint.as_ref());
        data[32..64].copy_from_slice(authority.as_ref());
        data[64..72].copy_from_slice(&amount.to_le_bytes());
        data[108] = 1;
        data
    }

    fn proof_data(body: &[u8]) -> Vec<u8> {
        let mut data = vec![0u8; 40 + body.len()];
        data[..4].copy_from_slice(b"ASPU");
        data[4..8].copy_from_slice(&(body.len() as u32).to_le_bytes());
        data[40..].copy_from_slice(body);
        data
    }

