        ) {
            return Err(OpeningError::Authentication.into());
        }
        emit(Phase::Merkle(i));
        aspis_core::r0::onchain_unhoisted::check_v1(
            &prepared.data,
            c.gamma,
            c.alpha,
            &proof,
