            &opening,
        )?;
        emit(Phase::V1(i));
    }
    aspis_core::r0::onchain_unhoisted::check_v2(
        &prepared.data,
        c.kappa,
        c.tau,
        c.alpha,
        &prepared.polynomial,
        &proof,
    )?;
    emit(Phase::V2);
    Ok(prepared.challenges)
}

/// Native differential reference at the R-E3 base.
#[cfg(all(feature = "r0-e4-reference", not(target_os = "solana")))]
pub fn r0_verify_re3(
    public: Public<'_>,
    bytes: &[u8],
    hash: HashFn,
